// Loads the Weekly Cases into public.weekly_cases and public.weekly_case_scoring.
//
// The cases are bundled in ./data (generated by scripts/weekly/export.mjs --write from scripts/weekly/cases/),
// so loading a week needs no SQL pasting: deploy this function, then call it.
//
//   GET  -> what would change, per week (writes nothing)
//   POST -> inserts missing weeks and updates the ones whose content changed
//
// It needs no sign-in on purpose: it can only write the case content bundled with it, only rows that differ,
// never a week that has closed, and never a stored status (archiving a case in the database is a veto). A second
// call writes nothing. The tables come from the migration drizzle/migrations/0044_weekly_cases.sql.
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { WEEKLY_CASES } from "./data/index.ts";
import { planSummary, planWeeks, type BundledWeek, type StoredCase, type StoredScoring } from "./plan.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body, null, 2), { status, headers: { ...corsHeaders, "Content-Type": "application/json" } });

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
  if (req.method !== "GET" && req.method !== "POST") return json({ error: "Use GET to preview or POST to load." }, 405);

  try {
    const db = createClient(Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!);
    const write = req.method === "POST";
    const bundled = WEEKLY_CASES as unknown as BundledWeek[];

    const weeks = bundled.map((b) => b.weekly_case.week_start);
    const { data: storedCases, error: caseError } = await db.from("weekly_cases")
      .select("id, week_start, market_id, kind, presented_by, title, topic, opens_at, closes_at, content").in("week_start", weeks);
    if (caseError) {
      const missing = /weekly_case/.test(caseError.message) && /(does not exist|schema cache|not find)/i.test(caseError.message);
      return json({
        error: missing
          ? "The weekly_cases table does not exist yet. Apply drizzle/migrations/0044_weekly_cases.sql first."
          : caseError.message,
      }, 400);
    }
    const ids = (storedCases ?? []).map((c) => c.id);
    const { data: storedScoring, error: scoringError } = ids.length
      ? await db.from("weekly_case_scoring").select("case_id, rubric, model_answer, common_traps, facts, time_sensitive, stale_after").in("case_id", ids)
      : { data: [], error: null };
    if (scoringError) return json({ error: scoringError.message }, 400);

    const plans = planWeeks(bundled, (storedCases ?? []) as StoredCase[], (storedScoring ?? []) as StoredScoring[]);
    const written: string[] = [];

    if (write) {
      const now = new Date().toISOString();
      for (const plan of plans) {
        const b = bundled.find((x) => x.weekly_case.week_start === plan.week_start)!;
        if (plan.action === "insert") {
          const { error } = await db.from("weekly_cases").insert(b.weekly_case);
          if (error) return json({ error: `${plan.week_start}: ${error.message}`, plans, written }, 500);
          const { error: keyError } = await db.from("weekly_case_scoring").upsert(b.scoring, { onConflict: "case_id" });
          if (keyError) return json({ error: `${plan.week_start} (grader key): ${keyError.message}`, plans, written }, 500);
          written.push(plan.week_start);
        } else if (plan.action === "update") {
          if (plan.caseChanged) {
            // The stored id and status are left as they are.
            const { id: _id, status: _status, week_start: _week, ...fields } = b.weekly_case;
            const { error } = await db.from("weekly_cases").update({ ...fields, updated_at: now }).eq("id", plan.id);
            if (error) return json({ error: `${plan.week_start}: ${error.message}`, plans, written }, 500);
          }
          if (plan.scoringChanged) {
            const { error } = await db.from("weekly_case_scoring").upsert({ ...b.scoring, case_id: plan.id }, { onConflict: "case_id" });
            if (error) return json({ error: `${plan.week_start} (grader key): ${error.message}`, plans, written }, 500);
          }
          written.push(plan.week_start);
        }
      }
    }

    return json({
      mode: write ? "loaded" : "preview (POST to load)",
      summary: planSummary(plans),
      weeks: plans,
      written,
    });
  } catch (err) {
    return json({ error: err instanceof Error ? err.message : String(err) }, 500);
  }
});
